@page "/recipes/{Category}"
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>@Category Recipes - RecipeShare</PageTitle>

<h1>@Category Recipes</h1>

@if (recipes.Any())
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-4">
                <div class="card h-100">
                    <div class="card-body">
                        <h4 class="card-title">@recipe.Title</h4>
                        <p class="card-text text-muted">
                            @if (recipe.RatingCount > 0)
                            {
                                <span>⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)</span>
                            }
                            else
                            {
                                <span>No ratings yet</span>
                            }
                        </p>
                        <a href="@($"recipe/{recipe.Id}")" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}
else
{
    <p>No recipes found in this category.</p>
}

<a href="/" class="btn btn-secondary mt-3">← Back to Categories</a>

@code {
    [Parameter]
    public string Category { get; set; } = string.Empty;

    private List<RecipeShare.Models.Recipe> recipes = new();

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetRecipesByCategory(Category);
    }
}

@page "/recipe/{Id:int}"
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

@if (recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
}
else
{
    <h1>@recipe.Title</h1>
    <p class="text-muted">Category: <a href="@($"recipes/{recipe.Category}")">@recipe.Category</a></p>

    <StarRating RecipeId="recipe.Id" CurrentRating="recipe.AverageRating" RatingCount="recipe.RatingCount" />

    <h3 class="mt-4">Ingredients</h3>
    <ul>
        @foreach (var ingredient in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol>
        @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            var text = step.Contains(". ") ? step[(step.IndexOf(". ") + 2)..] : step;
            <li>@text</li>
        }
    </ol>

    <a href="@($"recipes/{recipe.Category}")" class="btn btn-secondary mt-3">← Back to @recipe.Category</a>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private RecipeShare.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetRecipe(Id);
    }
}

@using RecipeShare.Services
@inject RecipeService RecipeService
@rendermode InteractiveServer

<div class="my-3 p-3 border rounded">
    <h5>Rate this recipe</h5>
    <div class="d-flex align-items-center gap-2">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <button class="btn btn-link p-0 fs-3 text-decoration-none"
                    @onclick="() => Rate(star)"
                    title="@($"Rate {star} star{(star > 1 ? "s" : "")}")">
                @(star <= selectedRating ? "★" : "☆")
            </button>
        }
        <span class="ms-3 text-muted">
            @if (RatingCount > 0)
            {
                @($"Average: {CurrentRating:F1} ({RatingCount} ratings)")
            }
            else
            {
                @("Be the first to rate!")
            }
        </span>
    </div>
    @if (hasRated)
    {
        <p class="text-success mt-2 mb-0">Thanks for rating! You gave @selectedRating star@(selectedRating > 1 ? "s" : "").</p>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int selectedRating;
    private bool hasRated;

    private void Rate(int stars)
    {
        selectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetRecipe(RecipeId);
        if (recipe != null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
        hasRated = true;
    }
}

@page "/submit"
@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation
@rendermode InteractiveServer

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

<EditForm Model="newRecipe" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
    <DataAnnotationsValidator />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" class="form-control" @bind-Value="newRecipe.Title" placeholder="e.g., Grandma's Apple Pie" />
        <ValidationMessage For="() => newRecipe.Title" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" class="form-select" @bind-Value="newRecipe.Category">
            <option value="">-- Select a category --</option>
            <option value="Italian">Italian</option>
            <option value="Indian">Indian</option>
            <option value="Mexican">Mexican</option>
            <option value="Desserts">Desserts</option>
            <option value="Other">Other</option>
        </InputSelect>
        <ValidationMessage For="() => newRecipe.Category" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="newRecipe.Ingredients" placeholder="1 cup flour&#10;2 eggs&#10;..." />
        <ValidationMessage For="() => newRecipe.Ingredients" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps (one per line)</label>
        <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="newRecipe.Steps" placeholder="1. Preheat oven to 350°F&#10;2. Mix dry ingredients&#10;..." />
        <ValidationMessage For="() => newRecipe.Steps" />
    </div>

    <button type="submit" class="btn btn-primary">Submit Recipe</button>
</EditForm>

@if (submitted)
{
    <div class="alert alert-success mt-3">
        Recipe "<strong>@submittedTitle</strong>" submitted successfully!
        <a href="@($"recipe/{submittedId}")">View it here</a>.
    </div>
}

@code {
    private Recipe newRecipe = new();
    private bool submitted;
    private string submittedTitle = string.Empty;
    private int submittedId;

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(newRecipe.Title) ||
            string.IsNullOrWhiteSpace(newRecipe.Category) ||
            string.IsNullOrWhiteSpace(newRecipe.Ingredients) ||
            string.IsNullOrWhiteSpace(newRecipe.Steps))
        {
            return;
        }

        RecipeService.AddRecipe(newRecipe);
        submittedTitle = newRecipe.Title;
        submittedId = newRecipe.Id;
        submitted = true;
        newRecipe = new();
    }
}

